<template>
  <main v-if="hasCartItems" class="order-shell">
    <header class="order-intro"><div><p class="order-kicker">Santa's Capybara Atelier</p><h1 class="order-title">Your order</h1><p>A considered selection from the holiday collection.</p></div><div class="order-badge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4zM8 3v4m8-4v4M7 11h10" /></svg><span>Illustrative order</span></div></header>
    <section class="order-layout" aria-label="Order details">
      <div class="order-items-panel"><div class="line-header"><span>Collection piece</span><span>Quantity</span><span>Total</span></div><article v-for="item in cartItems" :key="item.product.id" class="order-line"><div class="item-detail"><img :src="item.product.image" :alt="item.product.name" /><div class="line-product"><router-link :to="`/product/${item.product.id}`">{{ item.product.name }}</router-link><span>{{ formatPrice(item.product.price) }} each</span><button class="remove-link" type="button" :aria-label="`Remove ${item.product.name} from order`" @click="removeFromCart(item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M9 7l1-2h4l1 2m-9 0 1 13h10l1-13" /></svg>Remove</button></div></div><div class="quantity-stepper" :aria-label="`Quantity for ${item.product.name}`"><button type="button" :aria-label="`Decrease quantity for ${item.product.name}`" @click="decrementQuantity(item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14" /></svg></button><input v-model.number="item.quantity" type="number" min="1" :aria-label="`Quantity for ${item.product.name}`" @change="updateQuantity(item)" /><button type="button" :aria-label="`Increase quantity for ${item.product.name}`" @click="incrementQuantity(item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg></button></div><strong class="line-total">{{ formatPrice(item.product.price * item.quantity) }}</strong></article></div>
      <aside class="order-summary"><p class="summary-label">Order summary</p><div><span>Items</span><span>{{ itemCount }} pieces</span></div><div><span>Subtotal</span><strong>{{ formatPrice(calculateSubtotal()) }}</strong></div><div><span>Order</span><span>Illustrative</span></div><div class="summary-total"><span>Total</span><strong>{{ formatPrice(calculateSubtotal()) }}</strong></div><p class="summary-note">No payment or fulfilment is processed in this conference demo.</p><button class="submit-order" type="button" :disabled="isSubmitting" @click="submitOrder"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4zM8 3v4m8-4v4M7 11h10" /></svg>{{ isSubmitting ? 'Sending order…' : 'Send order' }}</button><button class="continue-button" type="button" @click="continueShopping">Continue browsing</button></aside>
    </section>
  </main>
  <main v-else class="empty-cart"><div class="empty-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 5h16v14H4zM8 3v4m8-4v4M7 11h10" /></svg></div><p>Santa's Capybara Atelier</p><h1>Your cart is waiting for a keepsake.</h1><span>Start with a little holiday warmth from the collection.</span><button type="button" @click="continueShopping">Browse the collection</button></main>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import { useCartStore } from '@/stores'
import { useRouter } from 'vue-router'
import type { CartItem } from '@/types'

const cartStore = useCartStore(); const router = useRouter(); const isSubmitting = ref(false)
const cartItems = computed(() => cartStore.items); const hasCartItems = computed(() => cartItems.value.length > 0); const itemCount = computed(() => cartItems.value.reduce((total, item) => total + item.quantity, 0))
const formatPrice = (price: number): string => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(price)
const calculateSubtotal = (): number => cartItems.value.reduce((total, item) => total + item.product.price * item.quantity, 0)
const updateQuantity = (item: CartItem): void => { if (item.quantity < 1 || Number.isNaN(item.quantity)) item.quantity = 1 }
const incrementQuantity = (item: CartItem): void => { item.quantity++; updateQuantity(item) }
const decrementQuantity = (item: CartItem): void => { item.quantity--; updateQuantity(item) }
const removeFromCart = (item: CartItem): void => { cartStore.removeItem(item.product.id) }
const continueShopping = (): void => { router.push('/') }
const submitOrder = (): void => { if (isSubmitting.value) return; isSubmitting.value = true; const order = { customerId: Math.floor(Math.random() * 10000000000).toString(), items: cartItems.value.map((item) => ({ productId: item.product.id, quantity: item.quantity, price: item.product.price })) }; fetch('/api/orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(order) }).then((response) => { if (!response.ok) throw new Error('Order request failed'); cartStore.clear(); alert('Order sent successfully') }).catch(() => { alert('The order could not be sent. Please try again.') }).finally(() => { isSubmitting.value = false }) }
</script>

<style scoped>
.order-shell, .empty-cart { width: min(1180px, calc(100% - 32px)); margin: 0 auto; padding: clamp(38px, 7vw, 84px) 0; }.order-intro { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 32px; }.order-kicker, .summary-label, .empty-cart > p { margin: 0 0 8px; color: var(--accent-color); font-size: .76rem; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }.order-title, .empty-cart h1 { margin: 0; font-size: clamp(2.3rem, 5vw, 4.4rem); line-height: 1; }.order-intro p:not(.order-kicker) { margin: 11px 0 0; color: var(--muted-text); }.order-badge { display: inline-flex; align-items: center; gap: 8px; padding: 9px 12px; border: 1px solid #d8bf8b; border-radius: 999px; background: #fff3d8; color: #72571f; font-size: .8rem; font-weight: 800; white-space: nowrap; }.order-badge svg, .submit-order svg, .empty-icon svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.8; }.order-layout { display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(280px, .8fr); gap: 28px; align-items: start; }.order-items-panel, .order-summary { border: 1px solid #d6c09a; border-radius: 14px; background: var(--card-background); box-shadow: var(--shadow); }.line-header, .order-line { display: grid; grid-template-columns: minmax(250px, 1fr) 140px 100px; gap: 18px; align-items: center; }.line-header { padding: 15px 22px; border-bottom: 1px solid #e4d4b6; color: var(--muted-text); font-size: .73rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }.line-header span:nth-child(2), .line-header span:last-child { text-align: right; }.order-line { padding: 18px 22px; border-bottom: 1px solid #eee1ca; }.order-line:last-child { border: 0; }.item-detail { display: flex; align-items: center; gap: 14px; min-width: 0; }.item-detail img { flex: 0 0 auto; width: 66px; height: 66px; border-radius: 10px; object-fit: cover; }.line-product { min-width: 0; }.line-product a { display: block; overflow: hidden; color: var(--text-color); font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }.line-product a:hover { color: var(--accent-color); }.line-product span { display: block; margin-top: 4px; color: var(--muted-text); font-size: .85rem; }.remove-link { min-height: auto; margin-top: 9px; padding: 0; background: transparent; color: var(--accent-color); box-shadow: none; font-size: .76rem; }.remove-link svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-linejoin: round; stroke-width: 1.8; }.remove-link:hover { transform: none; background: transparent; box-shadow: none; color: var(--accent-color-dark); }.quantity-stepper { display: inline-grid; grid-template-columns: 32px 42px 32px; justify-self: end; overflow: hidden; border: 1px solid #cdb68d; border-radius: 8px; background: #fffdf7; }.quantity-stepper button { min-height: 38px; padding: 0; border: 0; border-radius: 0; background: transparent; color: var(--primary-color); box-shadow: none; }.quantity-stepper button:hover { transform: none; background: #f0e2c4; box-shadow: none; }.quantity-stepper svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-linecap: round; stroke-width: 2; }.quantity-stepper input { width: 42px; border: 0; border-right: 1px solid #e1d0ad; border-left: 1px solid #e1d0ad; background: transparent; text-align: center; }.line-total { text-align: right; font-variant-numeric: tabular-nums; }.order-summary { padding: 24px; }.order-summary > div { display: flex; justify-content: space-between; gap: 18px; padding: 10px 0; color: var(--muted-text); font-size: .92rem; }.order-summary strong { color: var(--text-color); font-variant-numeric: tabular-nums; }.summary-total { margin-top: 8px; padding-top: 18px !important; border-top: 1px solid #d8c39f; color: var(--text-color) !important; font-size: 1.12rem !important; font-weight: 800; }.summary-note { margin: 16px 0 20px; color: var(--muted-text); font-size: .78rem; line-height: 1.5; }.submit-order, .continue-button { width: 100%; }.continue-button { margin-top: 9px; border-color: #cdb68d; background: transparent; color: var(--primary-color); box-shadow: none; }.continue-button:hover { background: #f4e7ce; color: var(--primary-color); box-shadow: none; }.submit-order:disabled { cursor: wait; opacity: .7; transform: none; }.empty-cart { display: flex; flex-direction: column; align-items: center; max-width: 680px; min-height: 65vh; justify-content: center; text-align: center; }.empty-icon { display: grid; place-items: center; width: 58px; height: 58px; margin-bottom: 22px; border-radius: 50%; background: var(--primary-color); color: #ecd392; }.empty-icon svg { width: 27px; height: 27px; }.empty-cart span { max-width: 38ch; margin: 14px 0 24px; color: var(--muted-text); line-height: 1.6; }
@media (max-width: 760px) { .order-intro { align-items: start; flex-direction: column; }.order-layout { grid-template-columns: 1fr; }.line-header { display: none; }.order-line { grid-template-columns: 1fr auto; gap: 12px; padding: 16px; }.item-detail { grid-column: 1; }.quantity-stepper { grid-column: 1; justify-self: start; }.line-total { grid-column: 2; grid-row: 1; }.order-summary { padding: 20px; } }
</style>
